new4='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    targets = [(r,c,grid[r][c]) for r in range(1,h-1) for c in range(1,w-1) if grid[r][c] != bg]
    def runs(axis, edge):
        n = w if axis == 'h' else h
        fixed = 0 if edge in ('top','left') else (h-1 if edge=='bottom' else w-1)
        vals = [grid[fixed][i] for i in range(n)] if axis=='h' else [grid[i][fixed] for i in range(n)]
        result=[]; i=0
        while i<n:
            if vals[i] == bg: i+=1; continue
            color=vals[i]; j=i+1
            while j<n and vals[j]==color: j+=1
            result.append((i,j,color)); i=j
        return result
    def pair_and_draw(axis, edge_a, edge_b):
        ra, rb = runs(axis, edge_a), runs(axis, edge_b)
        for a in ra:
            for b in rb:
                if a[2]!=b[2] or a[1]-a[0] != b[1]-b[0]: continue
                stripes=set()
                for r,c,color in targets:
                    pos = c if axis=='h' else r
                    if a[0] <= pos < a[1]: own, other, toward = a,b,edge_a
                    elif b[0] <= pos < b[1]: own, other, toward = b,a,edge_b
                    else: continue
                    stripes.add(other[0] + pos-own[0])
                    if axis == 'v':
                        step=-1 if toward=='left' else 1
                        x=c+step
                        while 0 < x < w-1 and grid[r][x] == bg:
                            out[r][x]=color; x+=step
                    else:
                        step=-1 if toward=='top' else 1
                        y=r+step
                        while 0 < y < h-1 and grid[y][c] == bg:
                            out[y][c]=color; y+=step
                if axis=='v':
                    for rr in stripes:
                        for x in range(1,w-1):
                            if grid[rr][x] == bg: out[rr][x]=a[2]
                else:
                    for cc in stripes:
                        for y in range(1,h-1):
                            if grid[y][cc] == bg: out[y][cc]=a[2]
                    # A stripe can continue to the far border if it joins the edge run there.
                    if edge_a=='top' and edge_b=='bottom' and any(cc==b[0]-1 or cc==b[1] for cc in stripes):
                        for cc in stripes:
                            if grid[h-1][cc] == bg: out[h-1][cc]=a[2]
                    if edge_a=='bottom' and edge_b=='top' and any(cc==b[0]-1 or cc==b[1] for cc in stripes):
                        for cc in stripes:
                            if grid[0][cc] == bg: out[0][cc]=a[2]
                # The source markers are distinguished from their rays.
                for r,c,color in targets:
                    pos=c if axis=='h' else r
                    if a[0] <= pos < a[1] or b[0] <= pos < b[1]:
                        out[r][c]=4
    pair_and_draw('v','left','right')
    pair_and_draw('h','top','bottom')
    return out
'''
